DECLARE packs jsonb := $pack$[{"modo":"HEREDA","tipo":"CAMBIO","clase":"PANTALLA","clave":"s22au_legacy_246_0","dueno":"PRODUCTO","codigo":"S22AU-246-1","efecto":"BLOQUEAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/246","solicitante":"Cristhian / Claude S22-BF"},"titulo":"Precio final y cálculo backend desde pricing vigente","alcance":"CLIENT_HOME","familia":"FINANCIAL_INTEGRITY_RECONCILIATION","impacto":"REVISAR","autoridad":"LEG-PRODUCTO","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"au_pricing_display"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"au_pricing_not_effective"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"au_price_processing_basis_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_tax_basis_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_payer_policy_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_final_mismatch"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_frontend_recalc"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_checkout_surprise"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_not_backend"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_service_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_component_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_defaults_override_partner"},"der":{"lit":true}}}},"naturaleza":"CONDUCTA","descripcion":"BLOQUEAR el cálculo o presentación del precio final que no provenga del backend ni de la configuración autorizada del aliado y su vigencia conforme a Q05 en public.lf_b2b_pricing_config. El procesamiento porcentual se calcula sobre el total recaudado. Cuando el cliente asume íntegramente los componentes aplicables, se utiliza la fórmula: base = monto_acuerdo + servicio_gestion + igv_servicio; precio_final = ROUND(base / (unidad − tasa_efectiva_niubiz), precisión_monetaria); procesamiento_niubiz = precio_final − base. El tipo y valor del servicio, tasa de procesamiento, tributación y participación de cada pagador se resuelven desde la configuración efectiva del aliado. La tasa efectiva considera niubiz_fee_taxable, niubiz_fee_includes_igv e igv_rate, sin presumir valores contractuales. Cuando exista reparto de costos, el backend incorpora exclusivamente los componentes atribuibles al cliente conforme a la configuración autorizada. El frontend muestra los importes resueltos por el backend, sin recálculos, identificación comercial del procesador ni cargos inesperados. El binding runtime permanece pendiente.","pruebas":[{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":true,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":true,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_pri