_not_backend"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_service_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_component_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"au_price_defaults_override_partner"},"der":{"lit":true}}}},"naturaleza":"CONDUCTA","descripcion":"BLOQUEAR el cálculo o presentación del precio final que no provenga del backend ni de la configuración autorizada del aliado y su vigencia conforme a Q05 en public.lf_b2b_pricing_config. El procesamiento porcentual se calcula sobre el total recaudado. Cuando el cliente asume íntegramente los componentes aplicables, se utiliza la fórmula: base = monto_acuerdo + servicio_gestion + igv_servicio; precio_final = ROUND(base / (unidad − tasa_efectiva_niubiz), precisión_monetaria); procesamiento_niubiz = precio_final − base. El tipo y valor del servicio, tasa de procesamiento, tributación y participación de cada pagador se resuelven desde la configuración efectiva del aliado. La tasa efectiva considera niubiz_fee_taxable, niubiz_fee_includes_igv e igv_rate, sin presumir valores contractuales. Cuando exista reparto de costos, el backend incorpora exclusivamente los componentes atribuibles al cliente conforme a la configuración autorizada. El frontend muestra los importes resueltos por el backend, sin recálculos, identificación comercial del procesador ni cargos inesperados. El binding runtime permanece pendiente.","pruebas":[{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":true,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":true,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":true,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":true,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":true,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":true,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":true,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":true,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":true,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":true,"au_price_defaults_override_partner":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":true,"au_pricing_not_effective":false,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"au_pricing_display":false,"au_pricing_not_effective":true,"au_price_processing_basis_wrong":false,"au_price_tax_basis_wrong":false,"au_price_payer_policy_wrong":false,"au_price_final_mismatch":false,"au_price_frontend_recalc":false,"au_checkout_surprise":false,"au_price_not_backend":false,"au_price_service_missing":false,"au_price_component_missing":false,"au_price_defaults_override_partner":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]}]$pack$::jsonb;
 a jsonb; ans jsonb; cd text; t record; h text; hashes jsonb:='{}'; vectors int:=0; n int:=0;
 before_replaced bigint; after_replaced bigint; b_leg jsonb; b_cfg jsonb; b_cov jsonb; b_rules jsonb; b_apps jsonb; b_other_versions jsonb; b_saly jsonb; suite text:=''; verdict text; val jsonb; lid int; links int:=0; b_v1 jsonb;
BEGIN
 SELECT jsonb_object_agg(regla,to_jsonb(x)-'vigente_hasta') INTO b_v1 FROM lf_ops.nucleo_regla_versiones x WHERE regla IN ('S22AU-246-1','S22AU-246-2') AND version=1;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_cov FROM lf_ops.lf_nucleo_cobertura_legada x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) INTO b_rules FROM lf_ops.nucleo_reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,nodo) INTO b_apps FROM lf_ops.nucleo_aplicaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_other_versions FROM lf_ops.nucleo_regla_versiones x WHERE regla NOT IN ('S22AU-246-1','S22AU-246-2');
 SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_reglas x),'versions',(SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM saly.nucleo_regla_versiones x),'facts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_hechos x)) INTO b_saly;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND before_replaced<>517 THEN RAISE EXCEPTION 'S22BF_PROD_COVERAGE_DRIFT %',before_replaced; END IF;
 IF EXISTS(SELECT 1 FROM saly.nucleo_reglas WHERE codigo IN ('S22AU-246-1','S22AU-246-2')) THEN RAISE EXCEPTION 'S22BF_SALY_SCOPE'; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_hechos WHERE codigo IN ('au_pricing_display','au_pricing_not_effective','au_price_processing_basis_wrong','au_price_tax_basis_wrong','au_price_payer_policy_wrong','au_price_final_mismatch','au_price_frontend_recalc','au_checkout_surprise','au_price_not_backend','au_price_service_missing','au_price_component_missing','au_price_defaults_override_partner') AND tipo_dato='boolean')<>12 THEN RAISE EXCEPTION 'S22BF_FACTS'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=a->>'codigo';
 IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo=cd AND capa_ejecucion='AMBOS') OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA' AND vigente_hasta IS NULL) THEN RAISE EXCEPTION 'S22BF_BASELINE %',cd; END IF;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22BF_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'S22BF_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,2);
 IF h IS NULL THEN RAISE EXCEPTION 'S22BF_HASH_MISSING %',cd; END IF;
 hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=2 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22BF_VECTOR_FAIL %',cd; END IF;
 vectors:=vectors+1; END LOOP;

 IF h IS DISTINCT FROM ($hash${"S22AU-246-1":"fb018f3af2e458e0e3185257bd136274ed20a5689d0f8de6af086d7c97cd585e","S22AU-246-2":"e777add54b1795d086fa255d52535daed74abc4d07d8a2d8f07f6d4272e9a970"}$hash$::jsonb->>cd) THEN RAISE EXCEPTION 'S22BF_ATTESTATION_DRIFT % %',cd,h; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',$pts${"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}$pts$::jsonb,'juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude V3 S22-BF; PASE job 140748064145, HEAD ad4b9e73, 26 vectors; independent approval');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22BF_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22BF_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=2 AND estado='PUBLICADA' AND vigente_hasta IS NULL) OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA' AND vigente_hasta IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo=cd AND capa_ejecucion='AMBOS') THEN RAISE EXCEPTION 'S22BF_PROMOTION_FAIL % %',cd,ans; END IF;
 IF (SELECT to_jsonb(x)-'vigente_hasta' FROM lf_ops.nucleo_regla_versiones x WHERE regla=cd AND version=1) IS DISTINCT FROM (b_v1->cd) THEN RAISE EXCEPTION 'S22BF_HISTORY_DRIFT %',cd; END IF;
 FOR lid IN SELECT unnest(ARRAY[246,247,253]) LOOP
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,2,'PARCIAL',$res$Fórmula sobre total recaudado corregida en V2. Falta configuración efectiva Q05 por aliado y vigencia, tributación contractual Niubiz, reparto autorizado y generación/conciliación de cotizaciones backend; binding runtime pendiente.$res$,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||(SELECT descripcion FROM lf_ops.reglas WHERE id=lid)||' NUCLEO: '||(a->>'descripcion'),'residual',$res$Fórmula sobre total recaudado corregida en V2. Falta configuración efectiva Q05 por aliado y vigencia, tributación contractual Niubiz, reparto autorizado y generación/conciliación de cotizaciones backend; binding runtime pendiente.$res$,'juicio','Claude V3 S22-BF PASE 140748064145'),h,'GPT / Claude S22-BF independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22BF_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>2 OR vectors<>26 THEN RAISE EXCEPTION 'S22BF_VECTOR_COUNT % %',n,vectors; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada x WHERE NOT (nucleo_codigo IN ('S22AU-246-1','S22AU-246-2') AND version_nucleo=2)) IS DISTINCT FROM b_cov OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM lf_ops.nucleo_reglas x) IS DISTINCT FROM b_rules OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones x) IS DISTINCT FROM b_apps OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones x WHERE regla NOT IN ('S22AU-246-1','S22AU-246-2')) IS DISTINCT FROM b_other_versions THEN RAISE EXCEPTION 'S22BF_INVARIANT_FAIL'; END IF;
 IF (SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_reglas x),'versions',(SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM saly.nucleo_regla_versiones x),'facts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_hechos x))) IS DISTINCT FROM b_saly THEN RAISE EXCEPTION 'S22BF_SALY_DRIFT'; END IF;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF after_replaced<>before_replaced OR EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id IN (246,247,248,253,250,254) AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S22BF_COVERAGE_DRIFT'; END IF;
 IF links<>(SELECT count(*)*2 FROM lf_ops.reglas WHERE id IN (246,247,253)) OR (SELECT count(*) FROM lf_ops.lf_nucleo_cobertura_legada WHERE nucleo_codigo IN ('S22AU-246-1','S22AU-246-2') AND version_nucleo=2 AND estado_cobertura='PARCIAL' AND length(evidencia->>'residual')>=15)<>links THEN RAISE EXCEPTION 'S22BF_PARTIAL_LINKS %',links; END IF;
 IF (SELECT count(DISTINCT legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id IN (246,247,248,253,250,254) AND estado_cobertura='PARCIAL')<>(SELECT count(*) FROM lf_ops.reglas WHERE id IN (246,247,248,253,250,254)) THEN RAISE EXCEPTION 'S22BF_PARTIAL_COVERAGE'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22BF_DPIG03'; END IF;
 FOR t IN SELECT * FROM (VALUES ('lf_ops','puerta','PUERTA 26/26'),('lf_ops','evaluacion','EVALUACION 23/23'),('lf_ops','cambio','CAMBIO 16/16'),('lf_ops','contrato','CONTRATO 4/4 (12 casos)'),('lf_ops','calculo','CALCULO 36/36'),('lf_ops','profundidad','PROFUNDIDAD 13/13'),('lf_ops','alcance_inverso','ALCANCE_INVERSO 10/10'),('saly','puerta','PUERTA 26/26'),('saly','evaluacion','EVALUACION 23/23'),('saly','cambio','CAMBIO 16/16'),('saly','contrato','CONTRATO 4/4 (12 casos)'),('saly','calculo','CALCULO 36/36'),('saly','profundidad','PROFUNDIDAD 13/13'),('saly','alcance_inverso','ALCANCE_INVERSO 10/10')) x(esquema,nombre,esperado) LOOP
 EXECUTE format('SELECT %I.%I()',t.esquema,'nucleo_autotest_'||t.nombre||'_v1') INTO verdict;
 IF verdict IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22BF_AUTOTEST_FAIL %.% %',t.esquema,t.nombre,verdict; END IF;
 suite:=concat_ws(';',suite,t.esquema||'.'||verdict);
 END LOOP;
 IF public.lf_nucleo_autotest_conjunto_v1() IS DISTINCT FROM 'CONJUNTO 5/5' OR lf_ops.lf_puente_autotest_v1() IS DISTINCT FROM 'PUENTE 8/8' OR lf_ops.lf_puente2_autotest_v1() IS DISTINCT FROM 'PUENTE2 6/6' THEN RAISE EXCEPTION 'S22BF_CONJUNTO_OR_PUENTE_FAIL'; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN ('S22AU-246-1','S22AU-246-2') AND version=2 AND estado='PUBLICADA' AND vigente_hasta IS NULL)<>2 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE codigo IN ('S22AU-246-1','S22AU-246-2') AND capa_ejecucion='AMBOS')<>2 THEN RAISE EXCEPTION 'S22BF_FINAL_READBACK'; END IF;
 RAISE NOTICE 'S22BF_FINAL_PASS promoted=% links=% coverage=%',n,links,after_replaced;
 RAISE NOTICE 'S22BF_PROOF PG=% CAMBIO=% VECTORES=% coverage_before=% coverage_after=% AMBOS=2 SALY_UNCHANGED DPIG03=0 J2=5/5 PUENTE=8/8 PUENTE2=6/6 suite=% hashes=%',current_setting('server_version_num'),n,vectors,before_replaced,after_replaced,suite,hashes;
END $bf$;
COMMIT;
